import pandas as pd
import numpy as np

# Load and convert data
data = pd.read_csv('/root/environment/data/ckd_lab_data.csv')

def convert_to_float(val):
    if pd.isna(val) or val == '' or val == 'nan':
        return np.nan
    val_str = str(val).strip()
    val_str = val_str.replace(',', '.')
    try:
        return float(val_str)
    except:
        return np.nan

for col in data.columns[1:]:
    data[col] = data[col].apply(convert_to_float)

data_clean = data.dropna().reset_index(drop=True)

print(f"Data shape after removing missing values: {data_clean.shape}")

# Define physiological ranges
physiological_ranges = {
    'Serum_Creatinine': (0.6, 1.2),
    'BUN': (7, 20),
    'eGFR': (60, 120),
    'Cystatin_C': (0.5, 1.0),
    'BUN_Creatinine_Ratio': (10, 20),
    'Sodium': (136, 145),
    'Potassium': (3.5, 5.0),
    'Chloride': (98, 107),
    'Bicarbonate': (23, 29),
    'Anion_Gap': (8, 16),
    'Magnesium': (1.7, 2.2),
    'Serum_Calcium': (8.5, 10.2),
    'Ionized_Calcium': (4.5, 5.3),
    'Phosphorus': (2.5, 4.5),
    'Intact_PTH': (15, 65),
    'Vitamin_D_25OH': (30, 100),
    'Vitamin_D_1_25OH': (20, 60),
    'Alkaline_Phosphatase': (30, 120),
    'Hemoglobin': (12.0, 17.5),
    'Hematocrit': (36, 46),
    'RBC_Count': (4.5, 5.9),
    'WBC_Count': (4.5, 11.0),
    'Platelet_Count': (150, 400),
    'Serum_Iron': (60, 170),
    'TIBC': (250, 425),
    'Transferrin_Saturation': (20, 50),
    'Ferritin': (30, 300),
    'Reticulocyte_Count': (0.5, 2.5),
    'Total_Bilirubin': (0.1, 1.2),
    'Direct_Bilirubin': (0.0, 0.3),
    'Albumin_Serum': (3.5, 5.5),
    'Total_Protein': (6.0, 8.3),
    'Prealbumin': (20, 40),
    'CRP': (0.0, 3.0),
    'Total_Cholesterol': (0, 200),
    'LDL_Cholesterol': (0, 130),
    'HDL_Cholesterol': (40, 200),
    'Triglycerides': (0, 150),
    'Non_HDL_Cholesterol': (0, 160),
    'Glucose': (70, 100),
    'HbA1c': (4.0, 5.6),
    'Fructosamine': (200, 285),
    'Uric_Acid': (3.5, 7.2),
    'Urine_Albumin': (0, 30),
    'Urine_Creatinine': (800, 2000),
    'Albumin_to_Creatinine_Ratio_Urine': (0, 30),
    'Protein_to_Creatinine_Ratio_Urine': (0, 150),
    'Urine_Protein': (0, 150),
    'Urine_pH': (4.5, 8.0),
    'Urine_Specific_Gravity': (1.005, 1.030),
    'BNP': (0, 100),
    'NT_proBNP': (0, 125),
    'Troponin_I': (0, 0.04),
    'Troponin_T': (0, 0.04),
    'Free_T4': (0.8, 1.8),
    'Free_T3': (2.3, 4.2),
    'pH_Arterial': (7.35, 7.45),
    'pCO2_Arterial': (35, 45),
    'pO2_Arterial': (80, 100),
    'Lactate': (0.5, 2.0),
    'Beta2_Microglobulin': (0.0, 2.4),
    'Aluminum': (0, 10),
}

print("\nApplying smart unit conversions based on physiological ranges...")

# Smart conversion: for each feature, determine if values are in wrong units
for feature, (min_val, max_val) in physiological_ranges.items():
    if feature not in data_clean.columns:
        continue

    col_data = data_clean[feature]
    out_of_range_count = ((col_data < min_val) | (col_data > max_val)).sum()

    if out_of_range_count == 0:
        continue

    # Determine appropriate conversion
    conversion_factor = None

    if feature == 'Serum_Creatinine':
        if (col_data > 1.5).any():
            conversion_factor = 1/88.4  # µmol/L to mg/dL
    elif feature == 'BUN':
        if (col_data > 25).any():
            conversion_factor = 1/2.8  # mmol/L to mg/dL
    elif feature == 'Magnesium':
        if (col_data > 3).any():
            conversion_factor = 1/2.43  # mmol/L to mg/dL
    elif feature == 'Serum_Calcium':
        if (col_data > 15).any():
            conversion_factor = 1/4.0  # mmol/L to mg/dL
    elif feature == 'Phosphorus':
        if (col_data > 6).any():
            conversion_factor = 1/3.1  # mmol/L to mg/dL
    elif feature == 'Albumin_Serum':
        if (col_data > 8).any():
            conversion_factor = 1/10  # g/L to g/dL
    elif feature == 'Total_Protein':
        if (col_data > 10).any():
            conversion_factor = 1/10  # g/L to g/dL
    elif feature == 'Hemoglobin':
        if (col_data > 20).any():
            conversion_factor = 1/10  # g/L to g/dL
        elif (col_data < 5).any() and (col_data > 0).any():
            conversion_factor = 10  # mmol/L to g/dL
    elif feature == 'Hematocrit':
        if (col_data > 60).any():
            conversion_factor = 1/10
    elif feature == 'Glucose':
        if (col_data > 1000).any():
            conversion_factor = 1/18  # µmol/L to mg/dL
    elif feature == 'Uric_Acid':
        if (col_data > 15).any():
            conversion_factor = 1/59.48  # µmol/L to mg/dL
    elif feature == 'Triglycerides':
        if (col_data > 1000).any():
            conversion_factor = 1/100  # mg/L to mg/dL
    elif feature == 'Total_Cholesterol':
        if (col_data > 1000).any():
            conversion_factor = 1/100  # mg/L to mg/dL
    elif feature == 'LDL_Cholesterol':
        if (col_data > 1000).any():
            conversion_factor = 1/100  # mg/L to mg/dL
    elif feature == 'HDL_Cholesterol':
        if (col_data > 1000).any():
            conversion_factor = 1/100  # mg/L to mg/dL
    elif feature == 'Ferritin':
        if (col_data > 500).any():
            conversion_factor = 1/10  # µg/L to ng/mL
    elif feature == 'Prealbumin':
        if (col_data > 50).any():
            conversion_factor = 1/10  # mg/L to mg/dL
    elif feature == 'pO2_Arterial':
        if (col_data > 200).any():
            conversion_factor = 1/7.5  # kPa to mmHg
    elif feature == 'Lactate':
        if (col_data > 10).any():
            conversion_factor = 1/11.2  # mmol/L to mg/dL
    elif feature == 'Beta2_Microglobulin':
        if (col_data > 10).any():
            conversion_factor = 1/1000  # µg/L to mg/L
    elif feature == 'Aluminum':
        if (col_data > 100).any():
            conversion_factor = 1/10
    elif feature == 'eGFR':
        if (col_data > 500).any():
            conversion_factor = 1/10

    if conversion_factor is not None:
        data_clean[feature] = data_clean[feature] * conversion_factor

# Round all values to 2 decimal places
for col in data_clean.columns[1:]:
    data_clean[col] = data_clean[col].round(2)

# Format as X.XX
for col in data_clean.columns[1:]:
    data_clean[col] = data_clean[col].apply(lambda x: f"{x:.2f}")

print(f"\nFinal data shape: {data_clean.shape}")
print(f"\nSample of final data:")
print(data_clean[['patient_id', 'Serum_Creatinine', 'Hemoglobin', 'Ferritin', 'BUN', 'pO2_Arterial', 'Lactate']].head(10))

# Save to output file
output_path = '/root/ckd_lab_data_harmonized.csv'
data_clean.to_csv(output_path, index=False)
print(f"\nData saved to {output_path}")

